#[serde(deny_unknown_fields)]
pub struct AttestationAck {
    /// The attestation was well formed and bound to a live nonce.
    #[serde(rename = "accepted")]
    pub accepted: bool,
    /// Session the attestation was filed under. (format: uuid)
    #[serde(rename = "sessionId")]
    pub session_id: String,
    /// Server time of receipt. (format: datetime)
    #[serde(rename = "receivedAt")]
    pub received_at: String,
    /// How often the companion should report in from now on. (min: 5, max: 3600)
    #[serde(rename = "heartbeatIntervalSeconds")]
    pub heartbeat_interval_seconds: i64,
}

/// Outcome of one policy requirement, kept so the block screen can name a concrete cause.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequirementResult {
    /// Which requirement was evaluated.
    #[serde(rename = "requirement")]
    pub requirement: RequirementId,
    /// Outcome under the active tier.
    #[serde(rename = "status")]
    pub status: RequirementStatus,
    /// Short human readable detail, for example the name of the driver blocking HVCI. (max length: 200)
    #[serde(rename = "detail", default, skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
}

/// The gate decision. Produced only by the backend attestation service (ADR 0004).
///
/// The resource pulls this; it is never pushed to the resource. That leaves no inbound
/// path an attacker could feed (design document 5.2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Verdict {
    /// allow, deny, or pending while still waiting.
    #[serde(rename = "decision")]
    pub decision: VerdictDecision,
    /// Session the verdict belongs to. (format: uuid)
    #[serde(rename = "sessionId")]
    pub session_id: String,
    /// Empty when the decision is allow. (max items: 16)
    #[serde(rename = "reasons")]
    pub reasons: Vec<DenyReason>,
    /// Per-requirement detail. (max items: 32)
    #[serde(rename = "requirements")]
    pub requirements: Vec<RequirementResult>,
    /// Player-facing instruction for the block screen. Naming the cause avoids a support ticket. (max length: 500)
    #[serde(rename = "remediation", default, skip_serializing_if = "Option::is_none")]
    pub remediation: Option<String>,
    /// Tier the evaluation ran against.
    #[serde(rename = "policyTier")]
    pub policy_tier: PolicyTier,
    /// When the verdict was decided. (format: datetime)
    #[serde(rename = "evaluatedAt")]
    pub evaluated_at: String,
    /// True when this allow was granted because the backend degraded, not because checks passed. Sessions admitted this way stay identifiable afterwards (ADR 0005).
    #[serde(rename = "failOpen")]
    pub fail_open: bool,
}

/// What the resource needs to decide whether a player in game may stay.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LivenessResponse {
    /// Session being asked about. (format: uuid)
    #[serde(rename = "sessionId")]
    pub session_id: String,
    /// Current lifecycle state.
    #[serde(rename = "state")]
    pub state: SessionState,
    /// Last companion check-in. (format: datetime)
    #[serde(rename = "lastHeartbeatAt", default, skip_serializing_if = "Option::is_none")]
    pub last_heartbeat_at: Option<String>,
    /// End of the grace period. While set, the player should see a visible warning. (format: datetime)
    #[serde(rename = "graceExpiresAt", default, skip_serializing_if = "Option::is_none")]
    pub grace_expires_at: Option<String>,
    /// True once the grace period has run out.
    #[serde(rename = "shouldKick")]
    pub should_kick: bool,
    /// Why the kick is due.
    #[serde(rename = "reason", default, skip_serializing_if = "Option::is_none")]
    pub reason: Option<DenyReason>,
}

/// Step 4: the NUI script pokes the companion on 127.0.0.1.
///
/// This is the only request the localhost endpoint accepts. It carries a nonce and
/// nothing else worth stealing — the backend URL is public and the server name is
/// cosmetic (ADR 0003).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LocalAttestCommand {
    /// Nonce issued by the backend and relayed through the game client. (format: hex, min length: 64, max length: 64)
    #[serde(rename = "nonce")]
    pub nonce: String,
    /// Where the companion should send the attestation. (max length: 256)
    #[serde(rename = "backendUrl")]
    pub backend_url: String,
    /// Display name shown in the companion window while the check runs. (max length: 128)
    #[serde(rename = "serverName", default, skip_serializing_if = "Option::is_none")]
    pub server_name: Option<String>,
    /// Protocol version the resource speaks. (min: 1)
    #[serde(rename = "protocolVersion")]
    pub protocol_version: i64,
}

/// The only thing the localhost endpoint ever returns.
///
/// It is an acknowledgement, not a result. Any local process can reach 127.0.0.1 — CORS
/// protects browsers, not native code — so the endpoint is built to be useless to a
/// caller other than the game client: it can trigger an attestation but can neither read
/// its outcome nor influence it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LocalAttestAck {
    /// The command was well formed and an attestation was started.
    #[serde(rename = "accepted")]
    pub accepted: bool,
    /// Running companion version. (format: semver, max length: 32)
    #[serde(rename = "companionVersion")]
    pub companion_version: String,
    /// Protocol version the companion speaks. (min: 1)
    #[serde(rename = "protocolVersion")]
    pub protocol_version: i64,
}

/// The companion asks the backend whether a player on this machine is connecting.
///
/// ADR 0010. FiveM does not run client resources while a player is held in a connect
/// deferral, so the localhost hop of ADR 0003 cannot carry the nonce at the moment the
/// gate needs it. The companion collects it here instead, and the backend decides which
/// pending session — if any — belongs to this machine.
///
/// The request carries no credential. It cannot: an attacker on this machine holds
/// whatever the companion holds. What limits the answer is the source address, which the
/// caller cannot choose.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CompanionPollRequest {
    /// Running companion version, so an outdated build is visible in the logs. (format: semver, max length: 32)
    #[serde(rename = "companionVersion")]
    pub companion_version: String,
    /// How long the backend may hold the request open before answering empty. (min: 0, max: 30)
    #[serde(rename = "waitSeconds")]
    pub wait_seconds: i64,
    /// Protocol version the companion speaks. (min: 1)
    #[serde(rename = "protocolVersion")]
    pub protocol_version: i64,
}

/// A nonce waiting for this machine, or nothing.
///
/// Carries no verdict and no history — only what the companion needs to run one scan and
/// report it. A local process that calls this endpoint learns that somebody at this
/// address is connecting, which it could see on the network anyway.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CompanionPollResponse {
    /// Whether a nonce is waiting. Every field below is absent if not.
    #[serde(rename = "pending")]
    pub pending: bool,
    /// Nonce to attest against. (format: hex, min length: 64, max length: 64)
    #[serde(rename = "nonce", default, skip_serializing_if = "Option::is_none")]
    pub nonce: Option<String>,
    /// Display name for the companion window while the check runs. (max length: 128)
    #[serde(rename = "serverName", default, skip_serializing_if = "Option::is_none")]
    pub server_name: Option<String>,
    /// Tier the session is evaluated at.
    #[serde(rename = "policyTier", default, skip_serializing_if = "Option::is_none")]
    pub policy_tier: Option<PolicyTier>,
    /// When the nonce stops being accepted. (format: datetime)
    #[serde(rename = "expiresAt", default, skip_serializing_if = "Option::is_none")]
    pub expires_at: Option<String>,
    /// Protocol version the backend speaks. (min: 1)
    #[serde(rename = "protocolVersion")]
    pub protocol_version: i64,
}

/// The companion asks how the attestation it just filed was judged.
///
/// ADR 0011, which relaxes ADR 0004. The reason and the remediation text are already
/// shown to the player by the FiveM connect screen, so withholding them here bought no
/// secrecy — it only made the companion window claim everything was fine while the
/// server was refusing the connection.
///
/// Answered only for a session id the caller already holds, which the companion learned
/// by attesting for it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CompanionOutcomeRequest {
    /// The session this companion attested for. (format: uuid)
    #[serde(rename = "sessionId")]
    pub session_id: String,
    /// How long the backend may hold the request open while the verdict is still forming. (min: 0, max: 10)
    #[serde(rename = "waitSeconds")]
    pub wait_seconds: i64,
    /// Protocol version the companion speaks. (min: 1)
    #[serde(rename = "protocolVersion")]
    pub protocol_version: i64,
}

/// Sent by the companion every HEARTBEAT_INTERVAL_SECONDS while a session is active.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct HeartbeatRequest {
    /// Session being kept alive. (format: uuid)
    #[serde(rename = "sessionId")]
    pub session_id: String,
    /// Repeated so a mid-session swap of the binary is visible. (format: hex, min length: 64, max length: 64)
    #[serde(rename = "companionBuildHash")]
    pub companion_build_hash: String,
    /// Seconds since the companion started. (min: 0)
    #[serde(rename = "uptimeSeconds")]
    pub uptime_seconds: i64,
    /// Whether the FiveM process is still running locally.
    #[serde(rename = "gameProcessPresent")]
    pub game_process_present: bool,
    /// Set on the last heartbeat the companion sends before it exits.
    ///
    /// Design document 5.5 wants a companion restart to survive the session and a
    /// deliberate exit not to. Without this the two are indistinguishable and both cost
    /// the full 210 seconds of interval plus grace — so quitting on purpose bought three
    /// and a half minutes of playing without a companion.
    ///
    /// It grants nobody anything: whoever can send this can already send
    /// gameProcessPresent false and end the same session.
    #[serde(rename = "closing", default, skip_serializing_if = "Option::is_none")]
    pub closing: Option<bool>,
    /// Protocol version the companion speaks. (min: 1)
    #[serde(rename = "protocolVersion")]
    pub protocol_version: i64,
}

/// The backend can shorten the interval or end the session, but never reveals a verdict.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct HeartbeatResponse {
    /// Heartbeat was accepted and the session extended.
    #[serde(rename = "acknowledged")]
    pub acknowledged: bool,
    /// When to report in next. (min: 5, max: 3600)
    #[serde(rename = "nextIntervalSeconds")]
    pub next_interval_seconds: i64,
    /// The companion should stop and tell the player the session ended.
    #[serde(rename = "terminate")]
    pub terminate: bool,
    /// Set when terminate is true.
    #[serde(rename = "terminateReason", default, skip_serializing_if = "Option::is_none")]
    pub terminate_reason: Option<DenyReason>,
}

/// Error envelope shared by every endpoint.
///
/// The message is for operators and logs. It never carries player data, and it never
/// explains which check failed to a caller that has not earned that information.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ProtocolError {
    /// Stable machine readable code, for example "nonce_expired". (max length: 64)
    #[serde(rename = "code")]
    pub code: String,
    /// Short operator-facing description. (max length: 500)
    #[serde(rename = "message")]
    pub message: String,
    /// Correlation id for support requests. (max length: 64)
    #[serde(rename = "requestId", default, skip_serializing_if = "Option::is_none")]
    pub request_id: Option<String>,
}

// --- Validation ------------------------------------------------------------

/// Format checks mirror the Lua patterns rather than the richer TypeScript ones. They
/// catch a wrong shape; the backend stays the authority on well-formedness.
mod check {
    pub fn length(value: &str, path: &str, min: Option<usize>, max: Option<usize>) -> Result<(), String> {
        if let Some(min) = min {
            if value.len() < min {
                return Err(format!("{path}: shorter than {min} characters"));
            }
        }
        if let Some(max) = max {
            if value.len() > max {
                return Err(format!("{path}: longer than {max} characters"));
            }
        }
        Ok(())
    }

    pub fn range(value: i64, path: &str, min: Option<i64>, max: Option<i64>) -> Result<(), String> {
        if let Some(min) = min {
            if value < min {
                return Err(format!("{path}: below the minimum of {min}"));
            }
        }
        if let Some(max) = max {
            if value > max {
                return Err(format!("{path}: above the maximum of {max}"));
            }
        }
        Ok(())
    }

    pub fn max_items<T>(value: &[T], path: &str, max: usize) -> Result<(), String> {
        if value.len() > max {
            return Err(format!("{path}: holds more than {max} items"));
        }
        Ok(())
    }

    pub fn hex(value: &str, path: &str) -> Result<(), String> {
        if value.chars().all(|c| c.is_ascii_hexdigit()) {
            Ok(())
        } else {
            Err(format!("{path}: does not look like hex"))
        }
    }

    pub fn base64(value: &str, path: &str) -> Result<(), String> {
        if value.chars().all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '/' || c == '=') {
            Ok(())
        } else {
            Err(format!("{path}: does not look like base64"))
        }
    }

    pub fn ip(value: &str, path: &str) -> Result<(), String> {
        if !value.is_empty() && value.chars().all(|c| c.is_ascii_hexdigit() || c == '.' || c == ':') {
            Ok(())
        } else {
            Err(format!("{path}: does not look like an IP address"))
        }
    }

    pub fn uuid(value: &str, path: &str) -> Result<(), String> {
        let bytes = value.as_bytes();
        let shaped = bytes.len() == 36
            && bytes.iter().enumerate().all(|(index, byte)| match index {
                8 | 13 | 18 | 23 => *byte == b'-',
                _ => byte.is_ascii_hexdigit(),
            });
        if shaped {
            Ok(())
        } else {
            Err(format!("{path}: does not look like a UUID"))
        }
    }

    pub fn datetime(value: &str, path: &str) -> Result<(), String> {
        // YYYY-MM-DDThh:mm:ss — anything after that is optional precision or a zone.
        const SHAPE: &[u8] = b"0000-00-00T00:00:00";
        let bytes = value.as_bytes();
        let shaped = bytes.len() >= SHAPE.len()
            && SHAPE.iter().enumerate().all(|(index, expected)| {
                if *expected == b'0' { bytes[index].is_ascii_digit() } else { bytes[index] == *expected }
            });
        if shaped {
            Ok(())
        } else {
            Err(format!("{path}: does not look like an ISO 8601 timestamp"))
        }
    }

    pub fn semver(value: &str, path: &str) -> Result<(), String> {
        let mut parts = value.split(['-', '+']).next().unwrap_or("").split('.');
        let major = parts.next().unwrap_or("");
        let minor = parts.next().unwrap_or("");
        let patch = parts.next().unwrap_or("");
        let numeric = |part: &str| !part.is_empty() && part.chars().all(|c| c.is_ascii_digit());
        if numeric(major) && numeric(minor) && numeric(patch) {
            Ok(())
        } else {
            Err(format!("{path}: does not look like a semantic version"))
        }
    }
}

impl SecurityFeatures {
    /// Checks the constraints serde cannot express — lengths, ranges and formats.
    ///
    /// Deserialization proves the shape; this proves the content. The companion runs it
    /// on everything it receives over the localhost endpoint, where the caller is
    /// any local process rather than the game client.
    pub fn validate(&self) -> Result<(), String> {
        // No field of this message carries a constraint beyond its type.
        Ok(())
    }
}

impl TpmInfo {
    /// Checks the constraints serde cannot express — lengths, ranges and formats.
    ///
    /// Deserialization proves the shape; this proves the content. The companion runs it
    /// on everything it receives over the localhost endpoint, where the caller is
    /// any local process rather than the game client.
    pub fn validate(&self) -> Result<(), String> {
        if let Some(inner) = &self.manufacturer {
            check::length(inner.as_str(), "TpmInfo.manufacturer", None, Some(64))?;
        }
        if let Some(inner) = &self.spec_version {
            check::length(inner.as_str(), "TpmInfo.specVersion", None, Some(32))?;
        }
        if let Some(inner) = &self.attestation_key_id {
            check::length(inner.as_str(), "TpmInfo.attestationKeyId", None, Some(128))?;
            check::hex(inner.as_str(), "TpmInfo.attestationKeyId")?;
        }
        Ok(())
    }
}

