impl SystemSnapshot {
    /// Checks the constraints serde cannot express — lengths, ranges and formats.
    ///
    /// Deserialization proves the shape; this proves the content. The companion runs it
    /// on everything it receives over the localhost endpoint, where the caller is
    /// any local process rather than the game client.
    pub fn validate(&self) -> Result<(), String> {
        check::range(self.schema_version, "SystemSnapshot.schemaVersion", Some(1), None)?;
        check::datetime(self.collected_at.as_str(), "SystemSnapshot.collectedAt")?;
        check::length(self.companion_version.as_str(), "SystemSnapshot.companionVersion", None, Some(32))?;
        check::semver(self.companion_version.as_str(), "SystemSnapshot.companionVersion")?;
        check::length(self.companion_build_hash.as_str(), "SystemSnapshot.companionBuildHash", Some(64), Some(64))?;
        check::hex(self.companion_build_hash.as_str(), "SystemSnapshot.companionBuildHash")?;
        check::length(self.os_build.as_str(), "SystemSnapshot.osBuild", None, Some(64))?;
        self.features.validate()?;
        self.tpm.validate()?;
        if let Some(inner) = &self.game_process {
            inner.validate()?;
        }
        check::max_items(self.probe_errors.as_slice(), "SystemSnapshot.probeErrors", 32)?;
        for item in self.probe_errors.iter() {
            check::length(item.as_str(), "SystemSnapshot.probeErrors[]", None, Some(200))?;
        }
        Ok(())
    }
}

